@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ### 🔧 Building a Custom dlt Source

    In this snippet we define a **custom dlt REST API source** that talks to the [GitHub API](https://docs.github.com/en/rest/issues/issues?apiVersion=2022-11-28&versionId=free-pro-team%40latest&productId=rest#list-repository-issues)

    The `make_github_issues_source` function lets us parameterize the **owner**, **repository**, and a time window (`days_back`).

    Inside the config:
    1. **Issues** → pulls all issues from the repo, supports incremental loading using the `updated_at` field so we don’t re-fetch everything each run.
    2. **Issue comments** → fetches all comments attached to issues, also with incremental loading.
    3. **Contributors** → lists who has contributed to the repo.

    Each resource is defined with:
    - a `path` (which GitHub API endpoint to call),
    - `params` (filters like `state=open`, pagination size, etc.), and
    - optionally an **incremental cursor** (so loads pick up only new/changed records since the last run).

    At the end, we return a ready-to-use dlt `rest_api_source(config)` object that can be plugged into a pipeline.
    """)
    return


@app.cell
def _():
    import dlt
    import pendulum

    from dlt.sources.rest_api import RESTAPIConfig, rest_api_source
    from dlt.destinations.adapters import lancedb_adapter


    def make_github_issues_source(owner: str, repo: str):
        config: RESTAPIConfig = {
            "client": {
                "base_url": "https://api.github.com",
                "headers": {
                    "Accept": "application/vnd.github+json",
                    "X-GitHub-Api-Version": "2022-11-28",
                },
                "paginator": "header_link",
            },
            "resources": [
                # 1) Issues
                {
                    "name": "issues",
                    "endpoint": {
                        "path": f"repos/{owner}/{repo}/issues",
                        "params": {
                            "state": "all",                 # or "open"
                            "sort": "updated",
                            "direction": "desc",
                            "per_page": 100,
                        },
                    },
                },
                # 2) Contributors
                {
                    "name": "contributors",
                    "endpoint": {
                        "path": f"repos/{owner}/{repo}/contributors",
                        "params": {"per_page": 100, "anon": "false"},
                    },
                },
            ],
        }
        return rest_api_source(config)
    return (
        RESTAPIConfig,
        dlt,
        lancedb_adapter,
        make_github_issues_source,
        pendulum,
        rest_api_source,
    )


