@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    Each time we refresh our data, we currently have to reload all issues from scratch. This is both time-consuming and expensive. A better approach is to only fetch issues that are new or have been updated since the last load, a method known in Data Engineering as incremental loading.

    Incremental loading means bringing in only the new or changed records, rather than reloading everything we already have.

    The GitHub API supports this with the `since` parameter:

    ```
    `since` string
    Only show results that were last updated after the given time. This is a timestamp in ISO 8601 format: YYYY-MM-DDTHH:MM:SSZ.
    ```
    """)
    return


@app.cell
def _(RESTAPIConfig, dlt, pendulum, rest_api_source):
    def make_github_issues_source_1(owner: str, repo: str, days_back: int=30):
        config: RESTAPIConfig = {'client': {'base_url': 'https://api.github.com', 'headers': {'Accept': 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28'}, 'paginator': 'header_link'}, 'resources': [{'name': 'issues', 'endpoint': {'path': f'repos/{owner}/{repo}/issues', 'params': {'state': 'all', 'since': '{incremental.last_value}', 'sort': 'updated_at', 'direction': 'desc', 'per_page': 100}, 'incremental': {'cursor_path': 'updated_at', 'initial_value': pendulum.today().subtract(days=days_back).to_iso8601_string()}}}, {'name': 'contributors', 'endpoint': {'path': f'repos/{owner}/{repo}/contributors', 'params': {'per_page': 100, 'anon': 'false'}}}]}
        return rest_api_source(config)
    test_pipeline_1 = dlt.pipeline(pipeline_name='test_pipeline_incremental', dataset_name='github_data', destination='duckdb')
    github_source_1 = make_github_issues_source_1(owner='dlt-hub', repo='dlt')
    info_1 = test_pipeline_1.run(github_source_1.add_limit(2))
    print(info_1)
    dataset_1 = test_pipeline_1.dataset()
    issues_df = dataset_1['issues'].df()
    print(f"Earliest issue: {issues_df['updated_at'].min()}")
    return


