@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ### 🧹 Cleaning Data with Custom Transformations

    One of the strengths of **dlt** pipelines is that you can apply **custom transformations** to every record as it flows through the pipeline.
    This lets you normalize or enrich data before it ever lands in the destination (like LanceDB).

    Here we define a `clean_description` function that tidies up GitHub issue text:

    - **Input:** each issue record (dict-like), with fields like `title` and `body`.
    - **Processing:**
      - Ensures text fields are valid strings.
      - Removes fenced code blocks (``` … ```).
      - Strips out HTML tags.
      - Collapses newlines and excessive whitespace.
      - Converts Markdown links into plain text.
    - **Output:** writes back:
      - The `title` as a safe string.
      - A new field `clean_description` that contains the cleaned-up issue body.

    When added to the source via `.add_map(clean_description)`, this function is applied to every record dlt extracts.

    👉 This demonstrates how dlt makes **ETL-style transforms** easy: you don’t just load raw data, you can *shape it on the fly* so it’s ready for downstream search, embeddings, and analytics.
    """)
    return


@app.cell
def _():
    import re
    def clean_description(record, meta=None):
        #  ensure both fields exist and are strings
        title = record.get("title") or ""
        if not isinstance(title, str):
            title = str(title)

        raw_text = record.get("body") or ""
        if not isinstance(raw_text, str):
            raw_text = str(raw_text)

        # Cleanups
        # remove fenced code blocks (across newlines)
        raw_text = re.sub(r'```.+?```', ' ', raw_text, flags=re.DOTALL)
        # remove html tags
        raw_text = re.sub(r'<.*?>', ' ', raw_text)
        # collapse newlines
        raw_text = re.sub(r'[\r\n]+', ' ', raw_text)
        # strip markdown links but keep the text
        raw_text = re.sub(r'\[(.*?)\]\(https?://.*?\)', r'\1', raw_text)
        # collapse whitespace
        clean_text = re.sub(r'\s+', ' ', raw_text).strip()

        # write back guaranteed strings
        record["title"] = title
        record["clean_description"] = clean_text

        return record
    return (clean_description,)


