@app.cell
def _(
    clean_description,
    dlt,
    lancedb_adapter,
    make_github_issues_source_2,
    os,
):
    from typing import List

    def run_pipeline(owner: str, repo: str, embed_cols: List[str], ns: str='demo', lancedb_dir=None):
        lancedb_dir = lancedb_dir or f'./data.lancedb_{ns}'
        os.environ['DESTINATION__LANCEDB__LANCE_URI'] = lancedb_dir
        os.environ['DESTINATION__LANCEDB__EMBEDDING_MODEL_PROVIDER'] = 'sentence-transformers'
        os.environ['DESTINATION__LANCEDB__EMBEDDING_MODEL'] = 'all-MiniLM-L6-v2'
        github_source = make_github_issues_source_2(owner, repo)
        github_source = github_source.add_limit(5)
        pipeline = dlt.pipeline(pipeline_name=f'github_issues_{ns}', destination='lancedb', dataset_name=f'github_data', progress='log')
        load_info = pipeline.run([lancedb_adapter(github_source.issues.add_map(clean_description), embed=embed_cols), github_source.issue_comments])
        return load_info
    return (run_pipeline,)


