@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ### 💬 Fetching Comments for Issues

    The `fetch_comments_for_issue_urls` function links **issues** to their **comments**:

    - **Input:** a list of issue `url` values from the issues table.
    - **Process:**
      - Reads the comments table into a DataFrame.
      - Keeps only the relevant fields (`issue_url`, `body`, `created_at`, `reactions__total_count`) if they exist.
      - Filters the comments to just those that belong to the requested issues.
    - **Output:** a DataFrame of comments tied directly to the selected issues.

    👉 This gives us the context we need to enrich issue retrieval with user discussions, which will later feed into summarization.
    """)
    return


@app.cell
def _(comments_table_1, pd):
    def fetch_comments_for_issue_urls(issue_urls: list[str]) -> pd.DataFrame:
        """
        Pull comments only for the given issue API URLs.
        Uses comments.issue_url to match issues.url.
        """
        if not issue_urls:
            return pd.DataFrame(columns=['issue_url', 'body', 'created_at', 'reactions__total_count'])
        cdf = comments_table_1.to_pandas()
        want = ['issue_url', 'body', 'created_at', 'reactions__total_count']
        present = [c for c in want if c in cdf.columns]
        cdf = cdf.loc[:, present]
        cdf = cdf.loc[cdf['issue_url'].isin(issue_urls)]
        return cdf
    return (fetch_comments_for_issue_urls,)


@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ### 📝 Attaching Comments as Context

    `attach_comments_context` enriches each issue with its discussion:

    - Pulls comments linked by `issue_url`.
    - Ranks them by reactions (then recency).
    - Keeps the top-N, trims length, and formats as a bullet list.
    - Combines **title + body + comments** into a single `context` field.

    👉 The result is a DataFrame where every issue includes a concise snapshot of both the problem and key community feedback.
    """)
    return


@app.cell
def _(fetch_comments_for_issue_urls, pd):
    def attach_comments_context(
        issues_df: pd.DataFrame,
        num_comments: int = 8,
        max_comment_length: int = 600
    ) -> pd.DataFrame:
        """
        For each retrieved issue row, gather its comments and build 'context':
        Title + Issue body (if present) + top comments (by reactions desc, then recency desc).
        Works with new schemas: join on issues.url ↔ comments.issue_url.
        """
        if issues_df.empty:
            return issues_df.assign(context="")

        issue_urls = issues_df["url"].dropna().unique().tolist()
        comments = fetch_comments_for_issue_urls(issue_urls)

        if comments.empty:
            base_ctx = (
                "Title: " + issues_df["title"].fillna("") + "\n\n" +
                ("Issue:\n" + issues_df["body"].fillna("") if "body" in issues_df.columns else "")
            ).str.strip()
            return issues_df.assign(context=base_ctx)

        # Normalize + rank
        if "reactions__total_count" not in comments.columns:
            comments["reactions__total_count"] = 0
        comments["reactions__total_count"] = comments["reactions__total_count"].fillna(0)

        if "created_at" in comments.columns:
            comments["created_at"] = pd.to_datetime(comments["created_at"], errors="coerce")
        else:
            comments["created_at"] = pd.NaT

        comments["body"] = comments["body"].fillna("").str.strip().str[:max_comment_length]

        comments = comments.sort_values(
            by=["reactions__total_count", "created_at"],
            ascending=[False, False],
            kind="mergesort"
        )

        # Top-N per issue_url → bullet list
        picked = (
            comments.groupby("issue_url")
                    .head(num_comments)
                    .groupby("issue_url")["body"]
                    .apply(lambda s: "\n- " + "\n- ".join([x for x in s if x]))
                    .reset_index()
                    .rename(columns={"issue_url": "url", "body": "comments_bulleted"})
        )

        merged = issues_df.merge(picked, on="url", how="left")
        merged["comments_bulleted"] = merged["comments_bulleted"].fillna("")

        merged["context"] = (
            "Title: " + merged["title"].fillna("") + "\n\n"
            + (("Issue:\n" + merged["body"].fillna("") + "\n\n") if "body" in merged.columns else "")
            + "Relevant comments:" + merged["comments_bulleted"]
        ).str.strip()

        return merged
    return (attach_comments_context,)


@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ### 🤖 Summarizing with OpenAI

    These functions turn retrieved issues + comments into a natural-language answer:

    - **`build_prompt`**
      - Takes the user’s query and a DataFrame of issues with `context`.
      - Formats a structured prompt:
        - User question
        - Top issues (title, body, comments)
        - Instructions to produce a short answer + actionable checklist.

    - **`summarize_solution`**
      - Selects the top N issues.
      - Builds the prompt.
      - Calls the OpenAI model (`gpt-4.1-mini` here) and returns the generated text.

    👉 This is the final step that converts structured LanceDB retrieval into a **human-readable solution**.
    """)
    return


@app.cell
def _(os, pd):
    from openai import OpenAI

    os.environ["OPENAI_API_KEY"] = ""


    client = OpenAI()
    OPENAI_MODEL = "gpt-4.1-mini"  # good balance of speed/quality; change if you prefer


    def build_prompt(user_query: str,
                     issues_df: pd.DataFrame,
                     max_chars_per_issue: int = 1800) -> str:
        """
        Build a summarization prompt for the OpenAI model.

        """
        header = (
            "You are a helpful assistant summarizing GitHub issues and their comments to help a user fix a problem.\n"
            "Use only the provided content. Be specific and actionable. Avoid speculation.\n\n"
            f"User question: {user_query}\n\n"
            "Context from top retrieved issues (title, body, selected comments):\n"
        )

        blocks = []
        for _, row in issues_df.iterrows():
            ctx = (row.get("context") or "")[:max_chars_per_issue]
            blocks.append(
                f"\n---\nIssue #{row.get('number','?')}: {row.get('title','')}\n{ctx}"
            )

        footer = (
            "\n---\n"
            "Produce:\n"
            "1) A concise 2–4 sentence answer tailored to the user's question.\n"
            "2) A 'Try this' checklist with 3–6 concrete steps.\n"
            "Do NOT repeat long stack traces or logs."
        )
        return header + "".join(blocks) + footer


    def summarize_solution(user_query: str,
                           issues_df: pd.DataFrame,
                           num_issues: int = 4) -> str:
        """
        Summarize potential solutions for a user query using retrieved GitHub issues and comments.

        """
        selected = issues_df.head(num_issues)
        prompt = build_prompt(user_query, selected)
        resp = client.responses.create(model=OPENAI_MODEL, input=prompt)
        return resp.output_text  # plain text output from the model
    return (summarize_solution,)


@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ### 🔗 End-to-End Issue Summarizer

    The `summarize_issue_solution` function ties everything together:

    1. **Retrieve** top candidate issues from LanceDB.
    2. **Enrich** them with comments using `attach_comments_context`.
    3. **Summarize** solutions via `summarize_solution` (OpenAI).
    4. **Append references** with issue numbers, titles, and links.

    👉 This single call runs the full pipeline: search → context → AI summary → references, giving the user a clear, actionable answer.
    """)
    return


@app.cell
def _(attach_comments_context, retrieve_issue_candidates, summarize_solution):
    def summarize_issue_solution(user_query: str,
                                 num_candidates: int = 25,
                                 num_issues: int = 4) -> str:
        """
        End-to-end helper: retrieve, enrich with comments, and summarize a solution.
        """
        # 1) retrieve issues
        candidates = retrieve_issue_candidates(user_query, num_candidates=num_candidates)
        if candidates.empty:
            return f"No related issues found for: {user_query}"

        # 2) attach comments context (uses your attach_comments_context helper)
        with_ctx = attach_comments_context(candidates)

        # 3) summarize (uses your summarize_solution that now accepts num_issues)
        answer = summarize_solution(user_query, with_ctx, num_issues=num_issues)

        # 4) references (the same issues we summarized)
        refs = "\n".join(
            f"- #{row.number}: {row.title} → {row.url}"
            for _, row in with_ctx.head(num_issues).iterrows()
        )

        return f"{answer}\n\nReferences:\n{refs}"
    return (summarize_issue_solution,)


